// Verify A_host and stage actual data
void* mappedA;
VK_CHECK(vkMapMemory(devs[0].dev, devs[0].memA_host, 0, BUFFER_SIZE, 0, &mappedA));
uint32_t* dataA = (uint32_t*)mappedA;
std::vector<uint32_t> stagedWords(WORD_COUNT);
memcpy(stagedWords.data(), mappedA, BUFFER_SIZE);
for (uint32_t i = 0; i < WORD_COUNT; ++i) {
    if (stagedWords[i] != PATTERN) { std::cerr << "Mismatch in A_host at " << i << "\n"; vkUnmapMemory(devs[0].dev, devs[0].memA_host); exit(1); }
}
vkUnmapMemory(devs[0].dev, devs[0].memA_host);

// Phase 2: Device 1 (AMD) - CPU Staging to B_host with ACTUAL A data
void* mappedB;
VK_CHECK(vkMapMemory(devs[1].dev, devs[1].memB_host, 0, BUFFER_SIZE, 0, &mappedB));
uint32_t* dataB = (uint32_t*)mappedB;
memcpy(dataB, stagedWords.data(), BUFFER_SIZE);
if (injectCorruption) dataB[WORD_COUNT / 2] ^= 0xFF; // Corrupt one word in staged copy
vkUnmapMemory(devs[1].dev, devs[1].memB_host);
